#!/usr/bin/env python3
"""Encrypted secret store backed by Fernet (AES-128-CBC + HMAC-SHA256).

- Key file holds a Fernet key, created with 0600 permissions.
- Store is a JSON file mapping secret name -> Fernet token.
"""

from __future__ import annotations

import argparse
import json
import os
import stat
import sys
import tempfile
from pathlib import Path

try:
    from cryptography.fernet import Fernet, InvalidToken
except ImportError:
    sys.exit("error: missing dependency 'cryptography' (pip install cryptography)")

DEFAULT_KEY_PATH = Path(os.environ.get("SECRETSTORE_KEY", "~/.config/rendercfg/secret.key")).expanduser()
DEFAULT_STORE_PATH = Path(os.environ.get("SECRETSTORE_FILE", "~/.config/rendercfg/secrets.json")).expanduser()


class SecretStore:
    def __init__(self, key_path: Path = DEFAULT_KEY_PATH, store_path: Path = DEFAULT_STORE_PATH):
        self.key_path = key_path
        self.store_path = store_path

    # -- key management -------------------------------------------------
    def init(self) -> None:
        """Generate a fresh key and an empty store with 0600 perms."""
        self.key_path.parent.mkdir(parents=True, exist_ok=True)
        self.store_path.parent.mkdir(parents=True, exist_ok=True)
        self._write_private(self.key_path, Fernet.generate_key() + b"\n")
        if not self.store_path.exists():
            self._write_private(self.store_path, b"{}\n")

    def _fernet(self) -> Fernet:
        try:
            return Fernet(self.key_path.read_bytes().strip())
        except FileNotFoundError:
            raise SystemExit(
                f"error: no key at {self.key_path}; run `secretstore init` first"
            )
        except ValueError:
            raise SystemExit(f"error: invalid Fernet key in {self.key_path}")

    @staticmethod
    def _write_private(path: Path, data: bytes) -> None:
        fd, tmp = tempfile.mkstemp(dir=path.parent, prefix=f".{path.name}.")
        os.fchmod(fd, 0o600)
        os.write(fd, data)
        os.close(fd)
        os.replace(tmp, path)

    # -- store io -------------------------------------------------------
    def _load(self) -> dict[str, str]:
        try:
            raw = json.loads(self.store_path.read_text())
            if not isinstance(raw, dict):
                raise SystemExit(f"error: {self.store_path} is not a JSON object")
            return raw
        except FileNotFoundError:
            raise SystemExit(f"error: store not found at {self.store_path}; run `secretstore init` first")

    def _save(self, secrets: dict[str, str]) -> None:
        payload = (json.dumps(secrets, indent=2, sort_keys=True) + "\n").encode()
        self._write_private(self.store_path, payload)

    # -- operations ------------------------------------------------------
    def set(self, name: str, value: str) -> None:
        secrets = self._load()
        token = self._fernet().encrypt(value.encode()).decode()
        secrets[name] = token
        self._save(secrets)

    def get(self, name: str) -> str:
        secrets = self._load()
        if name not in secrets:
            raise KeyError(name)
        try:
            return self._fernet().decrypt(secrets[name].encode()).decode()
        except InvalidToken:
            raise SystemExit(f"error: cannot decrypt '{name}' (wrong key or corrupted token)")

    def delete(self, name: str) -> bool:
        secrets = self._load()
        if name not in secrets:
            return False
        del secrets[name]
        self._save(secrets)
        return True

    def list_names(self) -> list[str]:
        return sorted(self._load())


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(prog="secretstore", description="Fernet-backed secret store")
    p.add_argument("--key", type=Path, default=DEFAULT_KEY_PATH)
    p.add_argument("--store", type=Path, default=DEFAULT_STORE_PATH)
    sub = p.add_subparsers(dest="cmd", required=True)

    sub.add_parser("init", help="create key and empty store")
    sp = sub.add_parser("set", help="set a secret (value via --stdin to avoid argv)")
    sp.add_argument("name")
    sp.add_argument("value", nargs="?")
    sp.add_argument("--stdin", action="store_true")
    gp = sub.add_parser("get", help="print a secret")
    gp.add_argument("name")
    lp = sub.add_parser("list", help="list secret names")
    dp = sub.add_parser("delete", help="remove a secret")
    dp.add_argument("name")

    ns = p.parse_args(argv)
    store = SecretStore(ns.key, ns.store)

    if ns.cmd == "init":
        store.init()
        print(f"key:   {ns.key}")
        print(f"store: {ns.store}")
    elif ns.cmd == "set":
        value = sys.stdin.read().rstrip("\n") if ns.stdin else ns.value
        if value is None:
            p.error("set requires VALUE or --stdin")
        store.set(ns.name, value)
        print(f"{ns.name} set ({len(store.list_names())} total)")
    elif ns.cmd == "get":
        print(store.get(ns.name))
    elif ns.cmd == "list":
        for name in store.list_names():
            print(name)
    elif ns.cmd == "delete":
        if not store.delete(ns.name):
            print(f"error: '{ns.name}' not found", file=sys.stderr)
            return 1
        print(f"{ns.name} deleted")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

